#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

#define STACK_CAPACITY 3U

struct Stack {
    int items[STACK_CAPACITY];
    size_t count;
};

static bool stack_invariant(const struct Stack *stack)
{
    return stack != NULL && stack->count <= STACK_CAPACITY;
}

static bool stack_push(struct Stack *stack, int value)
{
    if (!stack_invariant(stack) || stack->count == STACK_CAPACITY) {
        return false;
    }
    stack->items[stack->count] = value;
    ++stack->count;
    return true;
}

static bool stack_pop(struct Stack *stack, int *value)
{
    if (!stack_invariant(stack) || value == NULL || stack->count == 0U) {
        return false;
    }
    --stack->count;
    *value = stack->items[stack->count];
    return true;
}

static bool check(bool condition, const char *message)
{
    if (!condition) {
        printf("TEST FAILED: %s\n", message);
        return false;
    }
    return true;
}

int main(void)
{
    struct Stack stack = {{0}, 0U};
    int value = 0;

    if (!check(stack_invariant(&stack), "initial invariant")) return 1;
    if (!check(!stack_pop(&stack, &value), "pop empty stack")) return 1;
    if (!check(stack.count == 0U, "empty pop leaves count unchanged")) return 1;

    if (!check(stack_push(&stack, 10), "push first item")) return 1;
    if (!check(stack_invariant(&stack) && stack.count == 1U,
               "invariant after first push")) return 1;
    if (!check(stack_push(&stack, 20), "push second item")) return 1;
    if (!check(stack_push(&stack, 30), "push third item")) return 1;
    if (!check(stack.count == STACK_CAPACITY, "stack reaches capacity")) return 1;

    if (!check(!stack_push(&stack, 40), "reject push when full")) return 1;
    if (!check(stack.count == STACK_CAPACITY, "failed push preserves count")) return 1;

    if (!check(stack_pop(&stack, &value) && value == 30,
               "pop follows LIFO order")) return 1;
    if (!check(stack_invariant(&stack), "invariant after pop")) return 1;
    if (!check(stack_push(&stack, 40), "push after freeing one slot")) return 1;

    if (!check(stack_pop(&stack, &value) && value == 40,
               "new top is removed first")) return 1;
    if (!check(stack_pop(&stack, &value) && value == 20,
               "second LIFO value")) return 1;
    if (!check(stack_pop(&stack, &value) && value == 10,
               "last LIFO value")) return 1;
    if (!check(!stack_pop(&stack, &value), "reject pop after becoming empty")) return 1;
    if (!check(stack_invariant(&stack) && stack.count == 0U,
               "final empty invariant")) return 1;

    puts("All stack boundary and invariant tests passed.");
    return 0;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

#define CAPACITY 16U
#define TEST_OPERATIONS 10000U

struct Queue {
    int data[CAPACITY];
    size_t head;
    size_t tail;
    size_t count;
};

struct ReferenceQueue {
    int data[CAPACITY];
    size_t count;
};

static uint32_t next_random(uint32_t *state)
{
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

static bool queue_valid(const struct Queue *queue)
{
    return queue != NULL &&
           queue->head < CAPACITY &&
           queue->tail < CAPACITY &&
           queue->count <= CAPACITY;
}

static bool enqueue(struct Queue *queue, int value)
{
    if (!queue_valid(queue) || queue->count == CAPACITY) return false;

    queue->data[queue->tail] = value;
    queue->tail = (queue->tail + 1U) % CAPACITY;
    ++queue->count;
    return true;
}

static bool dequeue(struct Queue *queue, int *value)
{
    if (!queue_valid(queue) || value == NULL || queue->count == 0U) {
        return false;
    }

    *value = queue->data[queue->head];
    queue->head = (queue->head + 1U) % CAPACITY;
    --queue->count;
    return true;
}

static bool reference_enqueue(struct ReferenceQueue *queue, int value)
{
    if (queue->count == CAPACITY) return false;
    queue->data[queue->count] = value;
    ++queue->count;
    return true;
}

static bool reference_dequeue(struct ReferenceQueue *queue, int *value)
{
    if (queue->count == 0U) return false;

    *value = queue->data[0];
    for (size_t i = 1U; i < queue->count; ++i) {
        queue->data[i - 1U] = queue->data[i];
    }
    --queue->count;
    return true;
}

int main(void)
{
    const uint32_t initial_seed = UINT32_C(0x13579BDF);
    uint32_t random_state = initial_seed;
    struct Queue actual = {{0}, 0U, 0U, 0U};
    struct ReferenceQueue expected = {{0}, 0U};
    size_t completed = 0U;

    for (size_t operation = 0U; operation < TEST_OPERATIONS; ++operation) {
        uint32_t choice = next_random(&random_state);
        bool do_enqueue = (choice & 1U) != 0U;

        if (do_enqueue) {
            int value = (int)(next_random(&random_state) % UINT32_C(2001))
                        - 1000;
            bool actual_result = enqueue(&actual, value);
            bool expected_result = reference_enqueue(&expected, value);

            if (actual_result != expected_result) {
                printf("Mismatch at operation %zu (seed %u): enqueue\n",
                       operation, (unsigned int)initial_seed);
                return 1;
            }
        } else {
            int actual_value = 0;
            int expected_value = 0;
            bool actual_result = dequeue(&actual, &actual_value);
            bool expected_result = reference_dequeue(&expected, &expected_value);

            if (actual_result != expected_result ||
                (actual_result && actual_value != expected_value)) {
                printf("Mismatch at operation %zu (seed %u): dequeue\n",
                       operation, (unsigned int)initial_seed);
                return 1;
            }
        }

        if (!queue_valid(&actual) || actual.count != expected.count) {
            printf("Invariant mismatch at operation %zu (seed %u)\n",
                   operation, (unsigned int)initial_seed);
            return 1;
        }
        ++completed;
    }

    printf("Passed %zu deterministic operations (seed %u).\n",
           completed, (unsigned int)initial_seed);
    return 0;
}
